    "task_id", "file_name", "ext_dir", "ext_file_path", "org_dir", "org_file_path", "sp2013_dir", "sp2013_file_path", "created_at", "source_db"
)
SELECT
    s."task_id" + (SELECT id_offset FROM _merge.id_offset WHERE table_name = 'MigrationTasks' AND source_db = 'cwp_opspj2'),
    s."file_name",
    s."ext_dir",
    s."ext_file_path",
    s."org_dir",
    s."org_file_path",
